package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.history.SheetAsOf;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The statements taken of the people on each sheet. Taking one binds each of the person's claims that
 * counts (OPEN, PENDING or SETTLED, but not an OPEN one deferred on the sheet's today, nor an unbound OPEN or PENDING one dated within one of their holds) to the figure it shows then, and leaves
 * each that does not count unbound;
 * it records the person's due-total then: the sum of what is due on those claims as each shows it, late
 * charges included (a claim with no figure is skipped), at most the sheet's cap. A late charge is never bound: it keeps following
 * the sheet's today.
 * <p>
 * A steward can cancel a person's last statement: the claims it bound become live again (a figure a
 * statement before it bound is not restored), and the person's statement before it is their last again.
 * <p>
 * A statement can also be taken as of an earlier date, of the sheet as it stood then (see
 * {@link #take(String, String, long, LocalDate)}).
 */
@Service
public class StatementService {

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final SettingsService settings;
    private final SheetHistory history;

    public StatementService(StatementRepository statements, ClaimRepository claims,
            PersonRepository people, SheetService sheets, Audit audit, RollupService rollup,
            SettingsService settings, SheetHistory history) {
        this.settings = settings;
        this.history = history;
        this.statements = statements;
        this.claims = claims;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** A statement taken, with the person's claims as it left them, newest first. */
    public record Taken(Statement statement, List<Claim> claims) {
    }

    /** The sheet's statements in the order they were taken. */
    @Transactional(readOnly = true)
    public List<Statement> list(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Take the person's statement now (see {@link #take(String, String, long, LocalDate)}). */
    @Transactional
    public Taken take(String sheetId, String user, long personId) {
        return take(sheetId, user, personId, null);
    }

    /**
     * Take the person's statement as of {@code asOf}, a date on or before the sheet's today (now when
     * null): it binds their claims that counted at the end of that date to their figures as they stood
     * then — every change made while the sheet's today was on or before it counts, every later one does
     * not, and it stands in for the sheet's today in every figure — and leaves every other claim of theirs
     * unbound. Its date is that date and its due-total that day's. Refused when the date is after the
     * sheet's today, and when the person was not yet on the sheet then.
     */
    @Transactional
    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        List<Claim> theirs = claims.lockBySheetIdAndPersonId(sheetId, personId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = sheets.today(sheetId);
        if (asOf != null && asOf.isAfter(today)) throw new StatementRefusedException("after the sheet's today");
        // What the statement is taken of: the person and their claims as they stood then, with the
        // rates and settings then, the statement's date standing in for the sheet's today.
        Person then = person;
        List<Claim> stood = theirs;
        RollupService.Basis basis = rollup.live(sheetId);
        if (asOf != null) {
            SheetAsOf sheet = history.asOf(sheetId, asOf);
            then = sheet.person(personId).orElseThrow(() -> new StatementRefusedException("not on the sheet then"));
            stood = sheet.claimsOf(personId);
            basis = sheet;
        }
        LocalDate date = basis.today();
        Map<Long, BigDecimal> figures = new HashMap<>();
        for (Claim claim : stood) {
            if (RollupService.countsLive(claim, then, date)) figures.put(claim.getId(), rollup.figureOf(claim, then, basis));
        }
        int counted = figures.size();
        // The person's due-total as shown (the sum of those claims' figures, at most the sheet's cap): n/a
        // when none of their claims has a figure and no rate applies.
        BigDecimal total = rollup.dueTotalOf(stood, then, basis);
        BigDecimal dueTotal = total == null ? null : total.setScale(2, RoundingMode.HALF_EVEN);
        Statement statement = statements.saveAndFlush(new Statement(sheetId, personId, date, dueTotal, counted));
        for (Claim claim : theirs) {
            if (figures.containsKey(claim.getId())) claim.bind(figures.get(claim.getId()), statement.getId());
            else claim.unbind();
        }
        claims.flush();
        List<String> fields = new ArrayList<>(List.of("name=" + person.getName(),
                "due-total=" + (dueTotal == null ? RollupService.NONE : dueTotal.toPlainString()), "claims=" + counted));
        if (asOf != null) fields.add("asof=" + asOf);
        audit.change("STATEMENT", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return new Taken(statement, theirs);
    }

    /** Cancel the person's last statement: the claims it bound become live again. Refused when the user is
     * not a steward of the sheet, and when the person has no statement. */
    @Transactional
    public Taken cancelLast(String sheetId, String user, long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new StatementNotStewardException();
        List<Claim> theirs = claims.lockBySheetIdAndPersonId(sheetId, personId);
        Statement last = statements.findFirstBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)
                .orElseThrow(StatementNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        for (Claim claim : theirs) {
            if (claim.isStated() && last.getId().equals(claim.getStatedBy())) claim.unbind();
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        audit.change("STATEMENT_CANCELLED", sheetId, user, "name=" + person.getName(), "due-total="
                + (last.getDueTotal() == null ? RollupService.NONE : last.getDueTotal().toPlainString()));
        rollup.recordSince(sheetId, user, before);
        return new Taken(last, theirs);
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.pool.SheetPoolMember;
import net.officefloor.hq.app.pool.SheetPoolMemberRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A steward's merge of one person into another on the same sheet. The merged person's claims move to the
 * other (numbers and dates kept, listed after the other's claims in the order they were added, each
 * losing any figure a statement bound); their name and aliases become aliases of the other; their
 * patrons are added to the other's (not the other themselves, no repeats), and anyone naming them as
 * patron names the other instead (no repeats); their pool memberships move to the other (shares added
 * where the other is already a member), and any due-total a closed period fixed for them is added to
 * the other's. Their statements, holds, watchers and contact are dropped, and they leave the sheet.
 */
@Service
public class PersonMergeService {

    private final PersonRepository people;
    private final PersonPatronRepository patrons;
    private final PersonWatchRepository watches;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final SheetPoolMemberRepository poolMembers;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public PersonMergeService(PersonRepository people, PersonPatronRepository patrons, PersonWatchRepository watches,
            ClaimRepository claims, StatementRepository statements, SheetPoolMemberRepository poolMembers,
            PeriodRepository periods, SettingsService settings, SheetService sheets, RollupService rollup,
            Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.periods = periods;
        this.settings = settings;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** Merges the person {@code personId} into {@code intoId}, returning the person merged into; refused
     * unless the user is a steward, for the person themselves, and when either is retired. */
    @Transactional
    public Person merge(String sheetId, String user, long personId, long intoId) {
        Person from = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        Person into = people.findByIdAndSheetId(intoId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD || from.getId().equals(into.getId())
                || from.isRetired() || into.isRetired()) {
            throw new PersonMergeException();
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);

        List<Claim> moved = new ArrayList<>(claims.lockBySheetIdAndPersonId(sheetId, from.getId()));
        Collections.reverse(moved);
        for (Claim claim : moved) {
            claim.setPersonId(into.getId());
            claim.unbind();
            claim.setListed(sheets.nextInSequence(sheetId, "listed"));
        }
        claims.flush();

        List<String> aliases = new ArrayList<>();
        aliases.add(from.getName());
        aliases.addAll(from.getAliases());

        for (PersonPatron named : patrons.findByPersonIdOrderByIdAsc(from.getId())) {
            Long patron = named.getPatronId();
            if (patron.equals(into.getId()) || patrons.existsByPersonIdAndPatronId(into.getId(), patron)) {
                patrons.delete(named);
            } else {
                named.setPersonId(into.getId());
            }
            patrons.flush();
        }
        for (PersonPatron naming : patrons.findByPatronIdOrderByIdAsc(from.getId())) {
            Long person = naming.getPersonId();
            if (person.equals(into.getId()) || patrons.existsByPersonIdAndPatronId(person, into.getId())) {
                patrons.delete(naming);
            } else {
                naming.setPatronId(into.getId());
            }
            patrons.flush();
        }

        for (SheetPoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
            var already = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
            if (already.isPresent()) {
                already.get().setShare(already.get().getShare().add(member.getShare()));
                poolMembers.delete(member);
            } else {
                member.setPersonId(into.getId());
            }
            poolMembers.flush();
        }

        periods.findBySheetIdOrderByFromAsc(sheetId).forEach(period -> period.mergePersonTotal(from.getId(), into.getId()));
        periods.flush();

        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()));
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
        statements.flush();
        watches.flush();

        people.delete(from);
        people.flush();
        aliases.forEach(into::addAlias);
        people.flush();

        audit.change("PERSON_MERGED", sheetId, user, "from=" + from.getName(), "into=" + into.getName());
        rollup.recordSince(sheetId, user, before);
        return into;
    }
}
